import{_ as r,C as i,o as s,c as o,ah as a,E as n}from"./chunks/framework.sPHStHqt.js";const f=JSON.parse('{"title":"Plan Management","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/plan-management.md","filePath":"subscriptions/plan-management.md","lastUpdated":1789630599000}'),l={name:"subscriptions/plan-management.md"};function h(c,e,p,g,d,u){const t=i("ImagePopup");return s(),o("div",null,[e[0]||(e[0]=a('<h1 id="plan-management" tabindex="-1">Plan Management <a class="header-anchor" href="#plan-management" aria-label="Permalink to &quot;Plan Management&quot;">​</a></h1><p>Plans are what your tenants subscribe to. This is where you build them — set the price, add an offer, cap how much a tenant can create, and decide whether the plan is sold monthly, yearly, or both.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to read the plans list</li><li>How to create a plan with monthly and yearly pricing</li><li>How to add an offer and resource limits</li><li>What a <strong>Trial Plan</strong> does differently</li></ul></div><h2 id="the-plans-list" tabindex="-1">The plans list <a class="header-anchor" href="#the-plans-list" aria-label="Permalink to &quot;The plans list&quot;">​</a></h2><p>Open <strong>Subscription → Plans</strong>.</p>',5)),n(t,{src:"/images/plans/plan-grid.png",alt:"Subscription plans list"}),e[1]||(e[1]=a('<p>Each row shows the plan&#39;s <strong>Name</strong> and <strong>Code</strong>, its <strong>Validity</strong> (which cycles it&#39;s sold on), its <strong>Discount Amount / Amount</strong> (an offer shows the original price struck through), how many <strong>Active Tenants</strong> are on it, whether it&#39;s <strong>Recommended</strong>, and its <strong>Status</strong>.</p><p>Select <strong>Create Plan</strong> to add one.</p><h2 id="creating-a-plan" tabindex="-1">Creating a plan <a class="header-anchor" href="#creating-a-plan" aria-label="Permalink to &quot;Creating a plan&quot;">​</a></h2>',3)),n(t,{src:"/images/plans/plan-create.png",alt:"Create Plan form"}),e[2]||(e[2]=a('<h3 id="name-and-code" tabindex="-1">Name and code <a class="header-anchor" href="#name-and-code" aria-label="Permalink to &quot;Name and code&quot;">​</a></h3><ul><li><strong>Name</strong> <em>(required)</em> — what tenants see on the pricing page, e.g. <em>Growth</em>.</li><li><strong>Code</strong> <em>(required)</em> — a unique internal identifier, e.g. <code>growth</code>. Lowercase, no spaces.</li><li><strong>Description</strong> <em>(required)</em> — the one-line pitch shown under the plan name.</li></ul><h3 id="billing-cycles-and-pricing" tabindex="-1">Billing cycles and pricing <a class="header-anchor" href="#billing-cycles-and-pricing" aria-label="Permalink to &quot;Billing cycles and pricing&quot;">​</a></h3><p>Under <strong>Billing Cycles</strong>, tick <strong>Monthly</strong>, <strong>Yearly</strong>, or both. You must enable at least one. The price fields appear for whichever you enable:</p><ul><li><strong>Monthly Price</strong> / <strong>Yearly Price</strong> — the list price for that cycle.</li><li><strong>Monthly Offer</strong> / <strong>Yearly Offer</strong> — an amount taken <em>off</em> the price. Leave blank for no discount. An offer can&#39;t be larger than the price.</li></ul><p>Enabling both cycles lets a tenant choose monthly or yearly on the pricing page, and Krayin shows how much the yearly option saves.</p><h3 id="plan-restrictions" tabindex="-1">Plan Restrictions <a class="header-anchor" href="#plan-restrictions" aria-label="Permalink to &quot;Plan Restrictions&quot;">​</a></h3><p>Restrictions cap what a tenant on this plan can create — team members, leads, contacts, and so on. Select <strong>Add Restriction</strong>, choose a <strong>Restriction Type</strong>, give it a <strong>Label</strong>, and set a <strong>Limit Value</strong>. Use <code>-1</code> for unlimited.</p><p>Add as many as the plan needs. A tenant who hits a limit is prompted to upgrade.</p><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p><strong>Permissions</strong> controls which CRM features the plan unlocks — <strong>All</strong> for everything, or <strong>Custom</strong> to hand-pick.</p><h3 id="the-switches" tabindex="-1">The switches <a class="header-anchor" href="#the-switches" aria-label="Permalink to &quot;The switches&quot;">​</a></h3><ul><li><strong>Status</strong> — turn on to publish the plan. A plan left off is hidden from tenants.</li><li><strong>Recommended</strong> — highlights the plan on the pricing page as the suggested choice.</li><li><strong>Trial Plan</strong> — see below.</li></ul><p>Select <strong>Save</strong> to publish. If the plan has a price, Krayin registers it with your payment gateway automatically, so tenants can pay for it right away — provided <a href="/settings/configuration">Stripe is connected</a>.</p><h2 id="trial-plans" tabindex="-1">Trial plans <a class="header-anchor" href="#trial-plans" aria-label="Permalink to &quot;Trial plans&quot;">​</a></h2><p>Turning on <strong>Trial Plan</strong> changes the plan fundamentally. As the form explains, a trial is <em>&quot;granted free for the configured number of days. A trial is never sent to a payment gateway and carries no price.&quot;</em></p><p>So a trial has no price fields and no billing cycle — it&#39;s a way in, not a paid tier. Its length is set once under <a href="/settings/configuration">Configuration</a>, and it&#39;s covered in full on <a href="/subscriptions/trials">Free Trials</a>.</p><h2 id="editing-a-plan" tabindex="-1">Editing a plan <a class="header-anchor" href="#editing-a-plan" aria-label="Permalink to &quot;Editing a plan&quot;">​</a></h2><p>The pencil icon opens the same form pre-filled.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Editing a live plan&#39;s price changes it for the gateway too. Tenants already subscribed keep their current price until renewal, but new subscribers pay the new one. Change published pricing deliberately.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>See who has subscribed → <a href="/subscriptions/subscribers">Subscribers</a></li><li>Set up the free trial → <a href="/subscriptions/trials">Free Trials</a></li><li>Connect Stripe so paid plans work → <a href="/settings/configuration">Configuration</a></li></ul>',22))])}const b=r(l,[["render",h]]);export{f as __pageData,b as default};
